// Hide / show row or column in a table
//    In BISS, input button is generated by following functions.
//        createFitTable()
//        createWideTable()
//        createShowColButton()
//    @param obj  A input element.
//                  Normally use "this". 
function showAllCols(obj){
  const table = searchParentTable(obj);
  for(let Ci = 0; Ci < nCol(table); Ci++){
    for(let Rj = 0; Rj < table.rows.length; Rj++){
      table.rows[Rj].cells[Ci].style.display = '';
    }
  }
  obj.parentNode.textContent = "";
}
// Hide the column of the clicked button, and add a button that brings it back.
function hideTableCol(obj){
  // console.log(obj.parentNode.parentNode.parentNode);
  const table = searchParentTable(obj);
  const c_no = obj.parentElement.cellIndex;
  const c_name = headerRow(table).cells[c_no].innerText;
  // console.log(c_name);
  for(let Rj = 0; Rj < table.rows.length; Rj++){
    table.rows[Rj].cells[c_no].style.display = 'none';
  }
  const span = document.getElementById(table.id.replace(/_tb$/, '_up')).lastElementChild;
  // tc: "Show "
  if(span.children.length === 0){
    span.textContent = "";
    span.appendChild( msgSpan('show_label') );
    span.appendChild( createInput({ type:"button", value: msg('all_cols'), 'data-msg': 'all_cols', onclick:"showAllCols(this)"}) );
  }
  span.appendChild( createShowColButton(c_name) );
}
// Show the column named on the clicked button, then drop that button.
function showCol(obj){
  // show col
  const c_name = obj.value;
  const table = searchParentTable(obj);
  const c_no = getColNames(table).indexOf(c_name);
  for(let Rj = 0; Rj < table.rows.length; Rj++){
      table.rows[Rj].cells[c_no].style.display = '';
  }
  // remove
  if(obj.parentNode.children.length === 3){ obj.parentNode.textContent = ""; } // 3: "Show: " + All cols + this col
  obj.remove();
}
// Hide or show the table that follows the clicked button.
function hideShowNext(obj){
  // console.log(obj);
  // console.log(obj.parentNode.nextElementSibling);
  const ns = moduleNS(obj);
  const span  = document.getElementById(ns + '_up').lastElementChild;  // hidden columns
  const table = document.getElementById(ns + '_tb');
  const dn    = document.getElementById(ns + '_dn');
  const shown = (table.style.display === 'none') ? '' : 'none';
  for(const part of [span, table, dn]){ part.style.display = shown; }
  setMsg(obj, (shown === 'none') ? 'show_table' : 'hide_table');
}
